import{j as e}from"./vendor-query-4Od-xAjI.js";import{u as r}from"./index-BlM3Br0Q.js";import{B as i}from"./BottomNavigation-BofPfofd.js";import{B as c}from"./button-B0cCx7fD.js";import{u as l}from"./vendor-react-QVN-0OmF.js";import{A as d}from"./arrow-right-C5_PDwQj.js";import{A as p}from"./arrow-left-J628nIY1.js";import"./vendor-supabase-Cv0iAapC.js";import"./vendor-motion-BkSUeLYQ.js";import"./briefcase-JOKe2xTC.js";import"./bell-Dia8keFf.js";import"./user-w_BmcUIw.js";function D(){const{isRTL:t}=r(),o=l(),n=t?[{t:"قبول الشروط",c:"باستخدام تطبيق Sovereign، فإنك توافق على هذه الشروط. إذا لم توافق، يرجى عدم استخدام التطبيق. يجب أن يكون عمرك 18 عاماً أو أكثر لاستخدام التطبيق."},{t:"وصف الخدمة",c:'Sovereign هو منصة تواصل تجاري تربط المشاهير والوكلاء والشركات عبر عروض عمل منظمة تسمى "بطاقات العروض" (Deal Cards). تتيح المنصة: إرسال الشركات لبطاقات العروض للمشاهير، استقبال المشاهير أو وكلائهم للعروض في صندوق العمل، قبول أو رفض العروض، وفتح محادثات مشفرة مرتبطة بالعروض المقبولة فقط. لا توجد رسائل عامة، لا تغذية اجتماعية، ولا رسائل مباشرة بدون عرض مقبول.'},{t:"أنواع الحسابات",c:"ثلاثة أنواع من الحسابات: المشاهير (يستقبلون العروض في صندوق العمل)، الوكلاء/المديرون (يديرون محادثات وعروض مشاهير متعددين عبر تفويض قابل للإلغاء)، والشركات (ترسل العروض). كل نوع له صلاحيات وواجهة مخصصة."},{t:"حسابك",c:"أنت مسؤول عن الحفاظ على أمان حسابك وكلمة مرورك. يجب أن تكون المعلومات التي تقدمها دقيقة وحقيقية. لا يُسمح بإنشاء حسابات مزيفة أو انتحال هوية الآخرين. الحسابات غير النشطة لمدة 12 شهراً قد يتم حذفها."},{t:"بطاقات العروض (Deal Cards)",c:"بطاقات العروض هي عروض عمل منظمة ترسلها الشركات للمشاهير مباشرة أو عبر الوكلاء. تحتوي على: نوع العرض، اسم الشركة، نطاق الميزانية، دورة الميزانية، الجدول الزمني، التفاصيل، المخرجات، الحصرية، والسبب. حالة البطاقة: قيد الانتظار، مقبول، مرفوض. القبول ينشئ محادثة مشفرة مرتبطة بالبطاقة وتبقى البطاقة مثبتة في المحادثة."},{t:"تفويض الوكلاء",c:"يمكن للمشاهير تفويض وكلاء لإدارة صندوق العمل والرد على العروض. الوكيل يرى المحادثات باسم المشهور ويرسل الردود. التفويض قابل للإلغاء في أي وقت من إعدادات المشهور. الوكيل لا يملك الحساب، بل يديره نيابة عن المشهور."},{t:"السلوك المقبول",c:"يُحظر: إرسال عروض وهمية أو مضللة، التحرش أو التنمر، انتحال هوية الآخرين، محاولة اختراق النظام، نشر محتوى غير قانوني، استخدام التطبيق لأي غرض غير قانوني، تجاوز حدود الإرسال في صندوق العمل، أو محاولة الالتفاف على قيود المنصة."},{t:"المحتوى والمسؤولية",c:"أنت مسؤول عن محتوى بطاقات العروض والرسائل التي ترسلها. نحتفظ بالحق في إزالة أي محتوى ينتهك هذه الشروط وتعليق أو حذف الحسابات المخالفة. لا نتحقق من صحة العروض قبل الإرسال، ولا نضمن نتائج الأعمال."},{t:"الملكية الفكرية",c:"أنت تمتلك المحتوى الذي تنشئه (بطاقات العروض، الرسائل). بإرسال محتوى عبر التطبيق، تمنحنا ترخيصاً محدوداً لمعالجة وتخزين هذا المحتوى لتقديم الخدمة. نحترم حقوق النشر ونتعامل مع شكاوى الانتهاك وفق الإجراءات المعمول بها."},{t:"الإبلاغ والحظر",c:"يمكنك الإبلاغ عن أي مستخدم مسيء أو عرض مخالف أو حظره. نتعامل مع البلاغات بجدية وسرعة. الاستخدام المتكرر للإبلاغ الكاذب قد يؤدي لتعليق حسابك."},{t:"إنهاء الحساب",c:"يمكنك حذف حسابك في أي وقت من صفحة الملف الشخصي. الحذف نهائي ويشمل جميع بياناتك: الرسائل، بطاقات العروض، روابط الوكالة، ومفاتيح التشفير. يمكننا تعليق أو إنهاء حسابك في حالة انتهاك هذه الشروط."},{t:"تحديد المسؤولية",c:'الخدمة مقدمة "كما هي". لا نضمن خلوها من الأخطاء أو الانقطاعات. لسنا مسؤولين عن محتوى العروض أو القرارات التجارية الناتجة عنها. مسؤوليتنا محدودة وفقاً للقانون المعمول به.'},{t:"القانون المعمول به",c:"تخضع هذه الشروط للقوانين المعمول بها. أي نزاعات تُحل عبر التحكيم الملزم ما لم ينص القانون المحلي على خلاف ذلك."},{t:"التغييرات",c:"سنخطرك بأي تغييرات جوهرية عبر إشعار داخل التطبيق. استمرارك في الاستخدام يعني موافقتك على الشروط المحدّثة."}]:[{t:"Acceptance of Terms",c:"By using Sovereign, you agree to these terms. If you do not agree, please do not use the app. You must be 18 years or older to use the app."},{t:"Service Description",c:"Sovereign is a business communication platform connecting celebrities, agents, and companies through structured work offers called Deal Cards. The platform enables: companies sending Deal Cards to celebrities, celebrities or their agents reviewing offers in a Work Inbox, accepting or declining offers, and opening encrypted conversations linked to accepted offers only. No public messages, no social feed, no free-form direct messages without an accepted Deal Card."},{t:"Account Types",c:"Three account types: Celebrities (receive offers in Work Inbox), Agents/Managers (manage conversations and offers for multiple celebrities via revocable delegation), and Companies (send offers). Each type has dedicated permissions and interface."},{t:"Your Account",c:"You are responsible for maintaining the security of your account and password. Information you provide must be accurate and truthful. Creating fake accounts or impersonating others is not allowed. Accounts inactive for 12 months may be deleted."},{t:"Deal Cards",c:"Deal Cards are structured work offers sent by companies to celebrities directly or via agents. They contain: deal type, company name, budget range, budget cycle, timeline, details, deliverables, exclusivity, and rationale. Card status: pending, accepted, declined. Acceptance creates an encrypted conversation linked to the card, with the Deal Card pinned in the conversation."},{t:"Agent Delegation",c:"Celebrities can delegate agents to manage their Work Inbox and respond to offers. Agents see conversations on behalf of the celebrity and send replies. Delegation is revocable at any time from celebrity settings. The agent does not own the account; they manage it on behalf of the celebrity."},{t:"Acceptable Conduct",c:"Prohibited: sending fake or misleading offers, harassment or bullying, impersonating others, attempting to hack the system, posting illegal content, any illegal use of the app, bypassing Work Inbox rate limits, or attempting to circumvent platform restrictions."},{t:"Content & Responsibility",c:"You are responsible for Deal Cards and messages you send. We reserve the right to remove content violating these terms and suspend or delete violating accounts. We do not pre-screen offers before sending, and we do not guarantee business outcomes."},{t:"Intellectual Property",c:"You own the content you create (Deal Cards, messages). By sending content through the app, you grant us a limited license to process and store it to provide the service. We respect copyrights and handle infringement complaints per applicable procedures."},{t:"Reporting & Blocking",c:"You can report or block any abusive user or non-compliant offer. We take reports seriously and act promptly. Repeated false reporting may result in account suspension."},{t:"Account Termination",c:"You can delete your account at any time from the Profile page. Deletion is permanent and includes all your data: messages, Deal Cards, agency links, and encryption keys. We may suspend or terminate your account for violating these terms."},{t:"Limitation of Liability",c:'The service is provided "as is." We do not guarantee it will be error-free or uninterrupted. We are not responsible for offer content or business decisions resulting from them. Our liability is limited as permitted by applicable law.'},{t:"Governing Law",c:"These terms are governed by applicable laws. Disputes shall be resolved through binding arbitration unless local law requires otherwise."},{t:"Changes",c:"We will notify you of any material changes via an in-app notification. Continued use constitutes acceptance of updated terms."}];return e.jsxs("div",{className:"min-h-screen bg-background",dir:t?"rtl":"ltr",children:[e.jsx("header",{className:"fixed top-0 right-0 left-0 z-50 bg-card/95 backdrop-blur-sm border-b border-border",children:e.jsxs("div",{className:"max-w-lg mx-auto flex h-14 items-center gap-3 px-4",children:[e.jsx(c,{variant:"ghost",size:"icon",onClick:()=>o(-1),className:"h-10 w-10 rounded-xl",children:t?e.jsx(d,{className:"h-5 w-5"}):e.jsx(p,{className:"h-5 w-5"})}),e.jsx("h1",{className:"font-bold text-lg",children:t?"شروط الخدمة":"Terms of Service"})]})}),e.jsxs("main",{className:"max-w-lg mx-auto pt-16 pb-24 px-4 space-y-6",children:[e.jsx("p",{className:"text-sm text-muted-foreground",children:t?"آخر تحديث: أبريل 2026":"Last updated: April 2026"}),n.map((a,s)=>e.jsxs("section",{children:[e.jsx("h2",{className:"text-base font-bold mb-2",children:a.t}),e.jsx("p",{className:"text-sm text-muted-foreground leading-relaxed",children:a.c})]},s))]}),e.jsx(i,{})]})}export{D as default};
